/**
 * The app, in Albanian.
 *
 * Keyed on the ENGLISH source string, exactly as the other tables are, because
 * that is what ui() is handed at the call site. One character out and the
 * lookup misses in silence: the app draws the English and nothing anywhere
 * reports a problem.
 *
 * WHO THIS IS FOR. Albanian speakers learning German — in Albania, Kosovo and
 * North Macedonia, and the many living in the German-speaking countries
 * already. The course they are doing is German, and this table is the app
 * around it. So it never explains Albanian grammar; it only says Ruaj,
 * Vazhdo, and Seria jote mbaroi.
 *
 * ADDRESS. Ti throughout, never ju: singular imperatives (Shkruaj, Dëgjo,
 * Vazhdo) and singular possessives (yt, jote). An app talking to one person
 * who chose to be here, not an office writing to a citizen. Diçka shkoi keq,
 * not Ka ndodhur një gabim.
 *
 * NO GENDER ON THE READER. Albanian adjectives agree — i gatshëm, e gatshme —
 * and this app does not know who is reading it. Every line that would have
 * needed one is written round: the perfect with kam, which never agrees (ke
 * hyrë, ke mbaruar), an invariant word such as gati, or a noun. Where an
 * adjective does agree, it agrees with a thing in the sentence, not with the
 * person.
 *
 * STANDARD ALBANIAN, with ë and ç wherever they belong, and guillemets « » for
 * quotation. Language names are lowercase in running text, as Albanian writes
 * them, and capitalised only where one stands alone as a label or a course.
 *
 * GERMAN STAYS GERMAN. The words a lesson teaches — Schultüte, Feierabend,
 * TÜV, Ausländerbehörde — are the lesson, so they are left as they are, and so
 * are the app's own name and the handful of proper names (Lucide, Tatoeba,
 * Twemoji) the other tables also carry unchanged.
 */
