  "Your own flashcards, studied with the same engine as the course. Type them, paste them, or pull them straight from our catalogue.": "Kartat e tua të mësimit, që mësohen me të njëjtin motor si kursi. Shkruaji, ngjiti ose merri drejtpërdrejt nga katalogu ynë.",
