  "Switch to Custom order and All sets to reorder by dragging or arrows.": "Kalo te «Renditja ime» dhe «Të gjitha setet», që t'i rirenditësh duke i tërhequr ose me shigjeta.",
  "No sets yet": "Ende nuk ka sete",
  "No sets in this view": "Nuk ka sete në këtë pamje",
  "Make a set for whatever keeps slipping — irregular verbs, words from a conversation, anything. You can pull cards from the catalogue instead of typing them.": "Krijo një set për çdo gjë që të ikën nga mendja — folje të parregullta, fjalë nga një bisedë, çfarëdo. Mund t'i marrësh kartat nga katalogu në vend që t'i shkruash.",
