  "Delete this folder? Its sets move to the top level.": "Ta fshish këtë dosje? Setet e saj kalojnë në nivelin kryesor.",
  "Empty. Drag a set here, or use \"Move to folder\" on any card.": "Bosh. Tërhiq një set këtu ose përdor «Zhvendos në dosje» te cilado kartë.",
  "Not in a folder": "Jashtë dosjeve",
  "Tip: in the editor, \"From catalogue\" searches every word and phrase the app already knows — genders, glosses and usage notes come with them, so you rarely have to type a card yourself.": "Këshillë: në editor, «Nga katalogu» kërkon në çdo fjalë e shprehje që aplikacioni i njeh tashmë — gjinitë, shpjegimet dhe shënimet e përdorimit vijnë bashkë me to, ndaj rrallë të duhet ta shkruash vetë një kartë.",
  "Column": "Kolona",
  "That file is larger than 5 MB. Split it into smaller files and try again.": "Ky skedar është më i madh se 5 MB. Ndaje në skedarë më të vegjël dhe provo sërish.",
  "No two-column rows were found.": "Nuk u gjet asnjë rresht me dy kolona.",
