  "Lessons": "Mësimet",
  "Work through practical {language} in short blocks: read, listen, choose, type, and translate.": "Mëso {language} në praktikë, me blloqe të shkurtra: lexo, dëgjo, zgjidh, shkruaj dhe përkthe.",
  "core modules": "module bazë",
