  "Lesson content": "Përmbajtja e mësimit",
  "Hide finished ({count})": "Fshih të përfunduarat ({count})",
  "Clear filters": "Pastro filtrat",
  "Finished lessons are put away — nothing is deleted, and any whose words have started to fade stay in the list so you can review them.": "Mësimet e përfunduara mënjanohen — asgjë nuk fshihet, dhe ato me fjalë që kanë nisur të zbehen mbeten në listë, që t'i përsëritësh.",
  "Show finished ({count})": "Shfaq të përfunduarat ({count})",
  "Select lessons": "Zgjidh mësime",
  "Deselect all": "Hiq të gjitha zgjedhjet",
  "Select all {count} shown": "Zgjidh të gjitha {count} që shfaqen",
  "Select lessons to pause several at once": "Zgjidh mësime për të pezulluar disa njëherësh",
  "Pause selected": "Pezullo të zgjedhurat",
  "Resume selected": "Rifillo të zgjedhurat",
  "Keep these packs in the course, but learn them last — after everything else.": "Mbaji këto paketa në kurs, por mësoji në fund — pas gjithçkaje tjetër.",
  "Not interested": "Nuk më intereson",
  "Normal priority": "Përparësi normale",
  "Nothing matches that": "Asgjë nuk përputhet me këtë",
  "Try a different word, or clear the filters to see every lesson again.": "Provo një fjalë tjetër ose pastro filtrat që të shohësh sërish të gjitha mësimet.",
  "Open": "Hap",
  "Paused": "Në pauzë",
  "Learned last": "Mësohet në fund",
  "Finished": "Përfunduar",
  "{count} of the items you learned here are past their review date, so you are assumed to have forgotten some of them. Answering them once each puts them back to full.": "{count} nga elementet që mësove këtu e kanë kaluar datën e përsëritjes, ndaj supozohet se ke harruar disa prej tyre. Po t'i përgjigjesh secilit një herë, numërohen sërish plotësisht.",
  "{count} fading": "{count} po zbehen",
  "learned": "të mësuara",
  "Conversation coverage": "Mbulimi i bisedave",
  "The current path covers greetings, daily routines, travel, food, questions, basic opinions, and common sentence patterns.": "Rruga aktuale përfshin përshëndetje, rutinën e përditshme, udhëtime, ushqim, pyetje, mendime të thjeshta dhe modele të zakonshme fjalish.",
  "Your mastery": "Përvetësimi yt",
  "{count} items": "{count} elemente",
  "remaining": "të mbetura",
  "Deselect": "Hiq zgjedhjen",
  "Select": "Zgjidh",
  "Play {language} audio": "Luaj audion në {language}",
  "German picks a different \"you\" for friends, for a group, and for politeness. English uses one word for all three.": "Gjermanishtja zgjedh një «ti» tjetër për miqtë, për një grup dhe për mirësjellje. Anglishtja përdor një fjalë të vetme për të tria.",
  "Graded in Listen mode — exposure only, not mastery.": "U vlerësua në mënyrën «Dëgjo» — vlen vetëm si kontakt, jo si përvetësim.",
  "Known": "E njohur",
  "Struggle": "Vështirësi",
  "To learn": "Për t'u mësuar",
  "Memory strength": "Forca e kujtesës",
  "Click a bar to set it directly.": "Kliko një shtyllë për ta caktuar drejtpërdrejt.",
  "Come back in {days} day (level {level} of 5)": "Vjen sërish pas {days} dite (niveli {level} nga 5)",
  "Come back in {days} days (level {level} of 5)": "Vjen sërish pas {days} ditësh (niveli {level} nga 5)",
  "never reviewed again": "nuk përsëritet më kurrë",
  "Its review is due today. Answer it once and it counts in full again, on a longer interval.": "Sot i vjen radha për përsëritje. Përgjigju një herë dhe do të numërohet sërish plotësisht, me një interval më të gjatë.",
  "due for review": "për t'u përsëritur sot",
  "{days} days past its review, so you are assumed to still recall {kept}% of it — that is how much it counts towards your total right now. It halves every {halfLife} days towards {floor}% and never drops below that. Getting it right once puts it back to 100%.": "{days} ditë pas afatit të përsëritjes, ndaj supozohet se e mban mend ende në masën {kept}% — aq vlen tani në totalin tënd. Çdo {halfLife} ditë kjo vlerë përgjysmohet drejt {floor}% dhe nuk zbret kurrë më poshtë. Një përgjigje e saktë e çon sërish në 100%.",
  "{days} days overdue · {kept}% remembered": "{days} ditë vonesë · {kept}% në kujtesë",
  "review in": "përsëritje pas",
  "days short": "ditësh",
  "How this count works": "Si llogaritet ky numër",
  "{count} item is fading right now.": "{count} element po zbehet tani.",
  "{count} items are fading right now.": "{count} elemente po zbehen tani.",
  "Show them": "Shfaqi",
  "This number is an estimate of what you'd remember right now — not a tally of everything you have ever seen.": "Ky numër është një vlerësim i asaj që do të mbaje mend tani — jo një numërim i gjithçkaje që ke parë ndonjëherë.",
  "Something you learned recently counts as a whole item. Something you have not seen for a long time counts as less, because you probably remember less of it. That is why the number can go down as well as up.": "Diçka që e ke mësuar së fundi numërohet si një element i plotë. Diçka që s'e ke parë prej kohësh numërohet më pak, sepse me gjasë të kujtohet më pak. Prandaj numri mund edhe të ulet, jo vetëm të rritet.",
  "For example: you had “Guten Morgen” down two months ago and have not seen it since, so it counts as 0.8 rather than 1. Answer it correctly once and it counts fully again, immediately.": "Për shembull: «Guten Morgen» e dije mirë dy muaj më parë dhe s'e ke parë që atëherë, ndaj numërohet 0,8 në vend të 1. Përgjigju saktë një herë dhe menjëherë numërohet sërish plotësisht.",
  "The more times you have recalled something correctly, the more slowly it slips. And nothing ever falls to zero — coming back to a word you once knew is far quicker than meeting it new.": "Sa më shumë herë ta kesh kujtuar saktë diçka, aq më ngadalë zbehet. Dhe asgjë nuk bie kurrë në zero — rikthimi te një fjalë që e dije dikur është shumë më i shpejtë sesa ta takosh për herë të parë.",
  "“Due” means today is its review day. “Fading” means that day has been and gone. Same items, just later — which is why a row shows one or the other, never both.": "«Për t'u përsëritur» do të thotë që sot është dita e përsëritjes. «Po zbehet» do të thotë që ajo ditë ka kaluar. Janë të njëjtat elemente, thjesht më vonë — prandaj një rresht tregon njërën ose tjetrën, kurrë të dyja.",
  "Never fades: starred items, words you marked mastered by hand, and anything you learned outside the app — there is no review schedule to measure those against. This is the same number your dashboard, profile and games use.": "Nuk zbehen kurrë: elementet me yll, fjalët që i ke shënuar vetë si të përvetësuara dhe gjithçka që ke mësuar jashtë aplikacionit — për to nuk ka plan përsëritjesh me të cilin të maten. I njëjti numër përdoret edhe në panelin kryesor, në profil dhe te lojërat.",
  "Word & sentence tracker": "Gjurmuesi i fjalëve & fjalive",
  "Loading your vocabulary catalog…": "Po ngarkohet katalogu i fjalorit tënd…",
  "Review what you know, mark struggles, or reset items back to learn again.": "Përsërit atë që di, shëno vështirësitë ose rivendos elementet që t'i mësosh sërish.",
