  "Most common first uses conversation usefulness, curriculum order, and then word frequency. Niche and extra-practice material stays later.": "«Më të shpeshtat së pari» mbështetet te dobishmëria në bisedë, te rendi i kurrikulës dhe pastaj te shpeshtësia e fjalëve. Materiali i specializuar dhe ushtrimet shtesë vijnë më vonë.",
  "Filters and sorting apply to the full tracker, not only the rows currently visible.": "Filtrat dhe renditja vlejnë për gjithë gjurmuesin, jo vetëm për rreshtat që shihen tani.",
