  "No tests yet. Your results will build up here so you can track progress.": "Ende asnjë test. Rezultatet e tua do të mblidhen këtu, që të ndjekësh përparimin.",
  "Timeline": "Kronologjia",
  "Every date the test asks about, in order. Tap an event to read more.": "Çdo datë për të cilën pyet testi, sipas radhës. Kliko një ngjarje për të lexuar më shumë.",
  "All": "Të gjitha",
