  "A score here changes nothing in your lessons — picking from four is recognition, and the lessons ask you to produce the word. It is a read on how the listening is going.": "Rezultati këtu nuk ndryshon asgjë në mësimet e tua — të zgjedhësh mes katër opsionesh është njohje, ndërsa mësimet të kërkojnë ta nxjerrësh vetë fjalën. Është thjesht një tregues se si po shkon dëgjimi.",
