  "There is nothing at that level and usefulness together. Widen either one and the queue comes back.": "Nuk ka asgjë që i plotëson njëkohësisht këtë nivel dhe këtë dobishmëri. Zgjero njërin prej tyre dhe radha rikthehet.",
  "Once the course content is loaded, everything you are learning becomes listenable here.": "Sapo të ngarkohet përmbajtja e kursit, gjithçka që po mëson mund të dëgjohet këtu.",
