  "Unmute Greek voice": "Rikthe zërin në greqisht",
  "Albanian voice": "Zëri në shqip",
  "Mute Albanian voice": "Hiq zërin në shqip",
  "Unmute Albanian voice": "Rikthe zërin në shqip",
  "Sound effects control correct and incorrect answer sounds. Voice controls apply to all spoken audio, including lessons, games, and pet speech.": "Kontrolli i efekteve zanore rregullon tingujt e përgjigjeve të sakta dhe të gabuara. Kontrollet e zërave vlejnë për gjithçka që flitet, përfshirë mësimet, lojërat dhe fjalët e kafshëzës.",
  "Read it and say it back": "Lexoje dhe ritregoje",
  "Passages": "Pjesë leximi",
  "German the way it actually reaches you — messages, notes, a rant about a parcel. Read the whole thing, then put each line into English. Hover any word you do not know; working out the sentence is the part that counts.": "Gjermanishtja siç të vjen në të vërtetë — mesazhe, shënime, një shfryrje për një pako. Lexoje të tërën, pastaj ktheje çdo rresht në anglisht. Kalo miun mbi çdo fjalë që s'e di; të zbërthesh fjalinë është ajo që vlen.",
  "{count} lines": "{count} rreshta",
  "All passages": "Të gjitha pjesët",
  "The whole thing, both ways": "I gjithë teksti, në të dyja gjuhët",
  "You marked {got} of {total} as understood.": "Shënove {got} nga {total} si të kuptuara.",
  "You wrote": "Ti shkrove",
  "Another passage": "Një pjesë tjetër",
  "Hover a word for its meaning": "Kalo miun mbi një fjalë për kuptimin e saj",
  "Put line {number} into English": "Ktheje rreshtin {number} në anglisht",
  "Say what it means, in your own words": "Thuaj çfarë do të thotë, me fjalët e tua",
  "Compare with the answer": "Krahaso me përgjigjen",
  "Show me": "Ma trego",
  "One natural English version": "Një version i natyrshëm në anglisht",
  "That's it — every idea is there.": "Pikërisht — çdo ide është aty.",
  "Close — one or two ideas short.": "Pothuajse — mungojnë një a dy ide.",
  "Some of the meaning is missing.": "Mungon një pjesë e kuptimit.",
  "Not in your version: {words}": "Mungojnë në versionin tënd: {words}",
  "Next line": "Rreshti tjetër",
  "I had it after all": "Në fakt e kisha saktë",
  "Your starting point": "Pika jote e nisjes",
  "Are you completely new to {language}?": "Po nis nga zeroja në {language}?",
  "Choose the route that fits you. You can change level later.": "Zgjidh rrugën që të përshtatet. Nivelin mund ta ndryshosh më vonë.",
  "Yes, start from the beginning": "Po, fillo nga e para",
  "Begin with greetings, basic questions, numbers, and everyday phrases.": "Nis me përshëndetjet, pyetjet bazë, numrat dhe shprehjet e përditshme.",
  "No, check my level": "Jo, kontrollo nivelin tim",
  "Answer 10 short questions so Micheon can choose a better starting point.": "Përgjigju 10 pyetjeve të shkurtra, që Micheon të zgjedhë një pikë nisjeje më të mirë.",
  "Starting point": "Pika e nisjes",
  "Recommended module": "Moduli i rekomanduar",
  "Vocabulary check": "Kontroll i fjalorit",
  "Starting point check": "Kontroll i pikës së nisjes",
  "Translate to {language}": "Përkthe në {language}",
  "{language} prompt": "Pyetja në {language}",
  "Type the {language} word": "Shkruaj fjalën në {language}",
  "Check answer": "Kontrollo përgjigjen",
  "and {n} more — click to choose": "dhe {n} të tjera — kliko për të zgjedhur",
  "Which part?": "Cila pjesë?",
  "Point at any part of the app, then click it.": "Vendos miun mbi cilëndo pjesë të aplikacionit, pastaj klikoje.",
  "Topics you are not interested in": "Temat që nuk të interesojnë",
  "These stay in your course and keep any progress — they are simply learned last, after everything else, in lessons and in Listen.": "Këto mbeten në kursin tënd dhe e ruajnë çdo përparim — thjesht mësohen të fundit, pas gjithçkaje tjetër, në mësime dhe te «Dëgjo».",
  "Give {topic} its normal place in the order again.": "Ktheje {topic} në vendin e zakonshëm në radhë.",
  "Search topics, like cooking or football…": "Kërko tema, si gatim ose futboll…",
  "Loading your lessons…": "Po ngarkohen mësimet e tua…",
  "The stages in a lesson": "Fazat e një mësimi",
  "Recommended picks the stages for each phrase: short when you pass the typing test, longer when you miss it. Or set them yourself, and how many times each one runs.": "Opsioni «Rekomandohet» zgjedh fazat për çdo shprehje: më pak kur e kalon testin e shkrimit, më shumë kur jo. Ose caktoji vetë, bashkë me sa herë kryhet secila.",
  "1 step for each new phrase": "1 hap për çdo shprehje të re",
  "{count} steps for each new phrase": "{count} hapa për çdo shprehje të re",
  "Always on": "Gjithmonë aktive",
  "Run {stage} fewer times": "Kryeje {stage} më pak herë",
  "Run {stage} more times": "Kryeje {stage} më shumë herë",
  "A phrase you already know still gets one quick recall, a single word skips the stages only a sentence can do, and a stage that needs sound is swapped out while the sound is off.": "Një shprehje që e di tashmë merr prapë një rikujtim të shpejtë, një fjalë e vetme i kapërcen fazat që vetëm një fjali mund t'i bëjë, dhe një fazë që kërkon zë zëvendësohet sa kohë zëri është i fikur.",
  "Tap a word to hear it": "Prek një fjalë për ta dëgjuar",
  "In your words": "Me fjalët e tua",
  "Practice this word": "Ushtrohu me këtë fjalë",
  "is muted": "është pa zë",
  "That is why nothing played. Turn it back on?": "Prandaj nuk u dëgjua asgjë. Ta rikthej zërin?",
  "Unmute": "Rikthe zërin",
  "Keep it muted": "Lëre pa zë",
  "That code is not complete. It is twenty letters and numbers.": "Ky kod nuk është i plotë. Ka njëzet shkronja dhe numra.",
  "That is your own code.": "Ky është kodi yt.",
  "They are already in your list.": "Ky person është tashmë në listën tënde.",
  "Asked them to connect. They have to say yes on their side.": "Kërkesa u dërgua. Tani duhet ta pranojë nga ana e vet.",
  "Connected": "U lidh",
  "Connecting…": "Po lidhet…",
  "Not connected: {why}": "Nuk u lidh: {why}",
  "Not connected": "Nuk u lidh",
  "Your circle": "Rrethi yt",
  "Friends": "Miqtë",
  "Their figures come straight from their app to yours. There is no account and no server holding them.": "Shifrat e tyre vijnë drejt nga aplikacioni i tyre te yti. Nuk ka llogari dhe asnjë server që i mban.",
  "Your code": "Kodi yt",
  "Copied": "U kopjua",
  "Add by code": "Shto me kod",
  "Paste their code": "Ngjit kodin që të dhanë",
  "Add friend": "Shto mik",
  "{name} wants to connect": "{name} do të lidhet me ty",
  "Accept": "Prano",
  "Decline": "Refuzo",
  "Search friends": "Kërko miq",
  "Search your friends": "Kërko te miqtë e tu",
  "Clear friend search": "Pastro kërkimin e miqve",
  "{n} days": "{n} ditë",
  "Current streak": "Seria aktuale",
  "{n} XP": "{n} XP",
  "Total XP": "XP gjithsej",
  "No friend matches that search": "Asnjë mik nuk përputhet me këtë kërkim",
