  "Click any cell to reveal it. Translate the prompt correctly to defuse it. Wrong answer = boom.": "Kliko cilëndo kuti për ta zbuluar. Përkthe saktë pyetjen për ta çaktivizuar. Përgjigje e gabuar = bum.",
