  "Read the {meaning} prompt, then steer into its {target} translation. Every correct answer gives you a new phrase. Avoid the wrong choices and enemy snakes.": "Lexo pyetjen në {meaning}, pastaj drejtohu te përkthimi i saj në {target}. Çdo përgjigje e saktë të jep një shprehje të re. Shmang zgjedhjet e gabuara dhe gjarpërinjtë kundërshtarë.",
  "Master the German articles! Guide your snake to consume words that match your target. Watch out for world boundaries and enemy bots!": "Përvetëso nyjet gjermane! Drejtoje gjarprin tënd te fjalët që përputhen me nyjen e synuar. Kujdes nga kufijtë e fushës dhe gjarpërinjtë kundërshtarë!",
