  "High Score": "Rekordi",
  "How to play": "Si luhet",
  "Move your mouse to steer. Hold click or Space to boost. Read the {meaning} prompt and collect its {target} translation. Wrong choices cost points; enemy snakes end the run.": "Lëviz miun për të drejtuar. Mbaj të shtypur butonin e miut ose tastin e hapësirës për të shpejtuar. Lexo pyetjen në {meaning} dhe mblidh përkthimin e saj në {target}. Zgjedhjet e gabuara të kushtojnë pikë; gjarpërinjtë kundërshtarë e mbyllin lojën.",
  "Move your mouse to steer. Hold click or Space to boost speed (costs score). Eat words matching the Target Article to grow. Avoid hitting Bots! If a bot hits your body, you get bonus points.": "Lëviz miun për të drejtuar. Mbaj të shtypur butonin e miut ose tastin e hapësirës për të shpejtuar (kushton pikë). Ha fjalët që përputhen me nyjen e synuar për t'u rritur. Mos u përplas me botët! Nëse një bot të godet trupin, merr pikë shtesë.",
