  "Set both voices together or tune English and German separately. Changes also apply to lessons, games, and the companion.": "Rregulloji të dy zërat njëherësh ose anglishten dhe gjermanishten veç e veç. Ndryshimet vlejnë edhe për mësimet, lojërat dhe shoqëruesen.",
