  "The meaning on a lesson card": "Kuptimi në kartën e mësimit",
  "On the card it sits under the sentence at a size you can read at a glance. Underneath keeps it small and out of the way, for practising without it.": "Në kartë, kuptimi qëndron nën fjali, aq i madh sa ta lexosh me një shikim. Poshtë kartës mbetet i vogël dhe mënjanë, për t'u ushtruar pa të.",
  "Typos in the meaning box": "Gabime shtypi në fushën e kuptimit",
  "Only affects the side you are not learning. The word you are being taught is always marked exactly.": "Vlen vetëm për anën që nuk po mëson. Fjala që po mëson vlerësohet gjithmonë me përpikëri.",
