  "Full forms": "Format e plota",
  "Practise the short, natural forms people use. Full forms stay visible and count as correct.": "Ushtro format e shkurtra dhe të natyrshme që përdorin njerëzit. Format e plota mbeten të dukshme dhe llogariten si të sakta.",
  "Practise complete standard forms for formal writing, careful listening, and test answers.": "Ushtro format e plota standarde për shkrim zyrtar, dëgjim të kujdesshëm dhe përgjigje testi.",
