  "Drag this header to detach and place it anywhere.": "Tërhiq këtë shirit për ta shkëputur dhe për ta vendosur kudo.",
  "You can change answers to earlier questions.": "Mund t'i ndryshosh përgjigjet e pyetjeve të mëparshme.",
  "No pet messages yet": "Ende asnjë mesazh nga kafshëza",
  "Tips and questions will appear here after the mascot speaks.": "Këshillat dhe pyetjet do të shfaqen këtu pasi të flasë kafshëza.",
  "Yes": "Po",
  "No": "Jo",
  "Let's practise some German.": "Hajde të ushtrojmë pak gjermanisht.",
  "Los geht's! Let's go.": "Los geht's! Ta nisim.",
  "German tip: when a word uses der, die, or das, learn them together — say “der Tisch”, not just “Tisch”.": "Këshillë për gjermanishten: kur një fjalë merr der, die ose das, mësoji bashkë — thuaj «der Tisch», jo vetëm «Tisch».",
  "German tip: in a normal German sentence, the verb comes second — “Heute gehe ich nach Hause.”": "Këshillë për gjermanishten: në një fjali të zakonshme gjermane, folja vjen e dyta — «Heute gehe ich nach Hause.»",
  "German tip: after weil or dass, put the verb at the end — “weil ich müde bin”.": "Këshillë për gjermanishten: pas weil ose dass, folja shkon në fund — «weil ich müde bin».",
  "German tip: German words for people, places, things, or ideas always start with a capital letter.": "Këshillë për gjermanishten: fjalët gjermane për njerëz, vende, sende ose ide nisin gjithmonë me shkronjë të madhe.",
  "German tip: some verbs split in two — “aufstehen” becomes “Ich stehe um sieben auf.”": "Këshillë për gjermanishten: disa folje ndahen më dysh — «aufstehen» bëhet «Ich stehe um sieben auf.»",
  "English tip: normal sentences usually put who or what first, then the action, then the rest — “I read the book.”": "Këshillë për anglishten: në një fjali të zakonshme, në krye vjen zakonisht kush ose çfarë, pastaj veprimi dhe në fund pjesa tjetër — «I read the book.»",
  "English tip: after can, must, should, or will, use the verb without “to” — “can go”, not “can to go”.": "Këshillë për anglishten: pas can, must, should ose will, folja vjen pa «to» — «can go», jo «can to go».",
  "English tip: for habits or facts, verbs with he, she, or it usually end in -s — “she works”, “he knows”.": "Këshillë për anglishten: për zakone ose fakte, foljet me he, she ose it zakonisht mbarojnë me -s — «she works», «he knows».",
  "English tip: describing words normally come before the thing — “a red car”. They stay the same — “a nice man”, “a nice woman”.": "Këshillë për anglishten: fjalët përshkruese zakonisht vijnë para sendit — «a red car». Ato nuk ndryshojnë — «a nice man», «a nice woman».",
  "English tip: choose “a” or “an” by sound, not spelling — “a university”, but “an hour”.": "Këshillë për anglishten: zgjidh «a» ose «an» sipas tingullit, jo sipas shkrimit — «a university», por «an hour».",
  "English tip: after “didn't”, use go, see, or do — not went, saw, or did: “I didn't go.”": "Këshillë për anglishten: pas «didn't» përdor go, see ose do — jo went, saw ose did: «I didn't go.»",
  "English tip: “cannot” is one word. Its short form is “can't”.": "Këshillë për anglishten: «cannot» shkruhet si një fjalë. Forma e shkurtër është «can't».",
  "English tip: “will not” becomes “won't”, never “willn't”.": "Këshillë për anglishten: «will not» bëhet «won't», kurrë «willn't».",
  "English tip: German “es gibt” becomes “there is” for one thing and “there are” for several — never “it gives”.": "Këshillë për anglishten: shprehja gjermane «es gibt» bëhet «there is» për një send dhe «there are» për disa — kurrë «it gives».",
  "English tip: when talking about the past, use “there was” for one thing and “there were” for several.": "Këshillë për anglishten: kur flet për të kaluarën, përdor «there was» për një send dhe «there were» për disa.",
  "English tip: do not use two negatives together — “I didn't see anything”, not “I didn't see nothing”.": "Këshillë për anglishten: mos përdor dy mohime bashkë — «I didn't see anything», jo «I didn't see nothing».",
  "English tip: “should not” becomes “shouldn't”. The same shortening gives “wouldn't”, “couldn't”, and “mustn't”.": "Këshillë për anglishten: «should not» bëhet «shouldn't». I njëjti shkurtim jep «wouldn't», «couldn't» dhe «mustn't».",
  "English tip: use “haven't” with I, you, we, or they, and “hasn't” with he, she, or it — “I haven't seen it yet”.": "Këshillë për anglishten: përdor «haven't» me I, you, we ose they, dhe «hasn't» me he, she ose it — «I haven't seen it yet».",
