  "Learn every Windows numpad code for German letters, then practise the characters in real words and sentences. Includes laptop and no-numpad options.": "Mëso të gjitha kodet e bllokut numerik në Windows për shkronjat gjermane, pastaj ushtrohu me to në fjalë dhe fjali të vërteta. Përfshin edhe mundësi për laptopë dhe tastiera pa bllok numerik.",
