  "Page background": "Sfondi i faqes",
  "The colour behind everything.": "Ngjyra pas gjithçkaje.",
  "Panel background": "Sfondi i paneleve",
  "The large panels that hold a screen's content.": "Panelet e mëdha që mbajnë përmbajtjen e një ekrani.",
  "Card background": "Sfondi i kartave",
  "Cards, list rows and settings blocks.": "Kartat, rreshtat e listave dhe blloqet e cilësimeve.",
  "Raised background": "Sfondi i ngritur",
  "Hovered rows, inputs and anything sitting on a card.": "Rreshtat nën kursor, fushat e shkrimit dhe gjithçka që qëndron mbi një kartë.",
  "Lines and outlines": "Vijat dhe konturet",
  "The hairlines between cards, rows and inputs.": "Vijat e holla mes kartave, rreshtave dhe fushave të shkrimit.",
  "Headings and anything you are meant to read first.": "Titujt dhe gjithçka që duhet lexuar në fillim.",
  "Secondary text": "Teksti dytësor",
  "Supporting lines under a heading.": "Rreshta plotësues nën një titull.",
  "Quiet text": "Teksti i zbehtë",
  "Captions, hints and small print.": "Mbishkrimet, sugjerimet dhe shkrimi i imët.",
  "Say": "Thuaj",
  "That works.": "Edhe kjo bën.",
  "You wanted": "Kërkohej",
  "relative clause": "fjali përcaktore",
  "passive": "pësore",
  "ihr · a group — you all, not one person": "ihr · një grup — «ju të gjithë», jo një person",
  "I am learning": "Po mësoj",
  "Starts over from the beginning": "Fillon sërish nga e para",
  "Comes back as soon as there is a slot": "Kthehet sapo të lirohet një vend",
  "Not confident": "Pa siguri",
  "Comes back soon, often within a day": "Kthehet shpejt, shpesh brenda një dite",
  "About 3 days away, sooner if you slip": "Pas rreth 3 ditësh, më herët nëse gabon",
  "About 10 days away, sooner if you slip": "Pas rreth 10 ditësh, më herët nëse gabon",
  "About 30 days away, sooner if you slip": "Pas rreth 30 ditësh, më herët nëse gabon",
  "About 180 days away, sooner if you slip": "Pas rreth 180 ditësh, më herët nëse gabon",
  "Never comes back at all": "Nuk kthehet më kurrë",
  "Tomorrow": "Nesër",
  "In 3 days": "Pas 3 ditësh",
  "In a week": "Pas një jave",
  "In a month": "Pas një muaji",
  "Nothing brings it back today": "Sot nuk e kthen më asgjë",
  "Held back until then": "Mbahet mënjanë deri atëherë",
  "Nothing will show this before then.": "Asgjë nuk do ta shfaqë para asaj kohe.",
  "Both languages read aloud while you do something else.": "Të dyja gjuhët lexohen me zë, ndërsa ti bën diçka tjetër.",
  "Right now: {total} cards at a time, each heard {passes}×. The first {total} play {passes} times over, then the next {total} do the same.": "Tani: {total} karta njëherësh, secila dëgjohet {passes}×. {total} kartat e para luhen {passes} herë radhazi, pastaj {total} të radhës bëjnë njësoj.",
  "Words and sentences": "Fjalë dhe fjali",
  "Words only": "Vetëm fjalë",
  "Sentences and phrases only": "Vetëm fjali dhe shprehje",
  "Straight away": "Menjëherë",
  "After 3 more cards": "Pas 3 kartash të tjera",
  "After 10 more cards": "Pas 10 kartash të tjera",
  "After 30 more cards": "Pas 30 kartash të tjera",
  "Three other cards go by first. Short enough that you are still holding the word when it comes back, which is the exercise short-term memory actually is.": "Fillimisht kalojnë tri karta të tjera. Aq pak sa, kur fjala kthehet, e mban ende në mend — dhe pikërisht ky është ushtrimi i kujtesës afatshkurtër.",
  "Ten other cards go by first. Far enough that you have to fetch the word back rather than still be carrying it, and near enough to do it several times in one sitting.": "Fillimisht kalojnë dhjetë karta të tjera. Aq larg sa fjalën duhet ta sjellësh sërish në mend, jo ta kesh ende me vete, dhe aq afër sa ta bësh këtë disa herë në një seancë.",
  "Thirty other cards go by first. About a session's worth on a narrow filter, so a word returns once you have genuinely moved on from it.": "Fillimisht kalojnë tridhjetë karta të tjera. Me një filtër të ngushtë, kjo është afërsisht sa një seancë, kështu që fjala kthehet vetëm pasi ta kesh lënë vërtet pas.",
  "After a few hours": "Pas disa orësh",
  "After a day": "Pas një dite",
  "When the review says so": "Kur e kërkon përsëritja",
  "No wait at all. Anything can play again the moment the order reaches it — which on a narrow filter can mean the same handful of cards all evening. Right for a first pass through a new pack, and not much else.": "Pa asnjë pritje. Çdo gjë mund të luhet sërish sapo t'i vijë radha — gjë që me një filtër të ngushtë mund të thotë të njëjtat pak karta gjithë mbrëmjen. Vlen për kalimin e parë nëpër një paketë të re, e për pak gjë tjetër.",
  "About four hours. Long enough that you have to remember it rather than recognise it from a minute ago, and short enough to meet it again the same day.": "Rreth katër orë. Aq gjatë sa duhet ta kujtosh, jo thjesht ta njohësh nga një minutë më parë, dhe aq shkurt sa ta hasësh sërish po atë ditë.",
  "A full day. This is the shortest gap the review ladder ever asks for, and the point at which hearing something again is recall rather than an echo.": "Një ditë e plotë. Ky është intervali më i shkurtër që kërkon ndonjëherë shkalla e përsëritjeve, dhe pika ku ta dëgjosh diçka sërish është kujtim, jo jehonë.",
  "Nothing you have answered correctly comes back until the review ladder says it is due — one day, then three, ten, thirty, a hundred and eighty. Anything you have heard but never answered waits a day.": "Asgjë që e ke gjetur saktë nuk kthehet para se t'i vijë radha në shkallën e përsëritjeve — pas një dite, pastaj tri, dhjetë, tridhjetë, njëqind e tetëdhjetë ditësh. Çdo gjë që e ke dëgjuar, por s'i je përgjigjur kurrë, pret një ditë.",
