  "Twemoji": "Twemoji",
  "The pictures beside the words. Around eight hundred of them ship with the app, so they look the same on every machine and work with no connection.": "Figurat pranë fjalëve. Rreth tetëqind prej tyre vijnë bashkë me aplikacionin, që të duken njësoj në çdo kompjuter dhe të funksionojnë pa internet.",
  "Tatoeba": "Tatoeba",
  "Part of the real-sentence practice. Most of the course is written for Micheon, and the share coming from here falls with every pack that replaces it.": "Pjesë e ushtrimeve me fjali të vërteta. Pjesa më e madhe e kursit është shkruar për Micheon, dhe pjesa që vjen nga këtu zvogëlohet me çdo paketë që e zëvendëson.",
  "Lucide": "Lucide",
  "The interface icons.": "Ikonat e ndërfaqes.",
  "Electron, React and Vite": "Electron, React dhe Vite",
  "What the desktop app is built with.": "Me çfarë është ndërtuar aplikacioni për kompjuter.",
  "Also stay over fullscreen games, watch-only — clicks pass straight through. Some machines still give the game up a frame for anything drawn over it.": "Qëndron edhe mbi lojërat në ekran të plotë, vetëm për shikim — klikimet kalojnë drejt e në lojë. Në disa kompjuterë, gjithçka që vizatohet mbi lojë i merr prapëseprapë asaj një kuadër.",
  "🌱 I'm new to coding": "🌱 Sapo kam filluar me programimin",
  "colour, practise": "colour, practise",
  "color, practice": "color, practice",
  "A1–A2 · Beginner": "A1–A2 · Nivel fillestar",
  "Everyday basics: greetings, ordering, simple questions about yourself.": "Bazat e përditshme: përshëndetje, porosi, pyetje të thjeshta për veten.",
  "B1 · Getting by": "B1 · Ia del mbanë",
  "Handling ordinary situations alone — appointments, plans, opinions in short.": "Përballon vetë situatat e zakonshme — takime, plane, mendime me pak fjalë.",
  "B2 · Conversational": "B2 · Bisedon lirshëm",
  "Keeping up with natives on familiar topics, and arguing a point.": "Mban ritmin me vendasit në tema të njohura dhe mbron një mendim.",
  "C1 · Advanced": "C1 · Nivel i avancuar",
  "Fluent and precise, including work, study and abstract subjects.": "Flet rrjedhshëm dhe saktë, edhe për punën, studimet dhe tema abstrakte.",
  "C2 · Near-native": "C2 · Pothuajse si gjuhë amtare",
  "Anything a native handles: idiom, nuance, humour, fast speech.": "Gjithçka që përballon një folës amtar: idioma, nuanca, humor, të folur të shpejtë.",
  "All items": "Të gjitha",
