  "Common words the themed packs never taught, bank ranks 29–904.": "Fjalë të zakonshme që nuk dolën kurrë në paketat tematike, vendet 29–904 në bankën e fjalëve.",
  "Frequency-ranked everyday German, bank ranks 375–447.": "Gjermanishtja e përditshme e renditur sipas shpeshtësisë, vendet 375–447 në bankën e fjalëve.",
