  "Frequency-ranked everyday German, bank ranks 614–683.": "Gjermanishtja e përditshme e renditur sipas shpeshtësisë, vendet 614–683 në bankën e fjalëve.",
  "Frequency-ranked everyday German, bank ranks 686–761.": "Gjermanishtja e përditshme e renditur sipas shpeshtësisë, vendet 686–761 në bankën e fjalëve.",
  "Frequency-ranked everyday German, bank ranks 762–834.": "Gjermanishtja e përditshme e renditur sipas shpeshtësisë, vendet 762–834 në bankën e fjalëve.",
  "Frequency-ranked everyday German, bank ranks 835–934.": "Gjermanishtja e përditshme e renditur sipas shpeshtësisë, vendet 835–934 në bankën e fjalëve.",
  "Frequency-ranked everyday German, bank ranks 937–1002.": "Gjermanishtja e përditshme e renditur sipas shpeshtësisë, vendet 937–1002 në bankën e fjalëve.",
  "Frequency-ranked everyday German, bank ranks 1003–1070.": "Gjermanishtja e përditshme e renditur sipas shpeshtësisë, vendet 1003–1070 në bankën e fjalëve.",
  "Frequency-ranked everyday German, bank ranks 1072–1154.": "Gjermanishtja e përditshme e renditur sipas shpeshtësisë, vendet 1072–1154 në bankën e fjalëve.",
  "Frequency-ranked everyday German, bank ranks 1155–1225.": "Gjermanishtja e përditshme e renditur sipas shpeshtësisë, vendet 1155–1225 në bankën e fjalëve.",
  "Common words the themed packs never taught, bank ranks 917–1726.": "Fjalë të zakonshme që nuk dolën kurrë në paketat tematike, vendet 917–1726 në bankën e fjalëve.",
  "Fandom and screen smalltalk: recommending a series without spoilers, binge confessions, the very German dubbing debate, celebrity gossip, and concert hype. \"Welche Serie schaust du gerade?\" has replaced the weather as the default opener.": "Bisedë e lehtë për fansat dhe ekranin: si të rekomandosh një serial pa spoilerë, rrëfimet e maratonave me seriale, debati shumë gjerman për dublimin, thashethemet për të famshmit dhe ethet para koncerteve. «Welche Serie schaust du gerade?» ia ka zënë vendin motit si hyrja e zakonshme në bisedë.",
  "Talking about music taste, playing instruments, and German concert & festival culture — from \"Was hörst du so?\" smalltalk to zelten am Gelände, the Zugabe chant, and the Festivalbändchen you never cut off.": "Si të flasësh për shijen muzikore, për instrumentin që i bie dhe për kulturën gjermane të koncerteve dhe festivaleve — nga biseda e lehtë me «Was hörst du so?» te zelten am Gelände, thirrjet për Zugabe dhe Festivalbändchen që nuk e pret kurrë.",
  "The German outdoor rituals: the sacred Sonntagsspaziergang, proper hiking with Brotzeit and a Hütte stop, summer days at the See — and the Deutsche Bahn survival kit for getting there: delays \"mal wieder\", missed Anschlüsse, platform changes and the dreaded Schienenersatzverkehr.": "Ritualet gjermane në natyrë: i shenjti Sonntagsspaziergang, ecja e vërtetë në mal me Brotzeit dhe një ndalesë te Hütte, ditët e verës te See — dhe paketa e mbijetesës me Deutsche Bahn për të mbërritur atje: vonesat «mal wieder», Anschlüsse të humbura, ndryshimet e binarit dhe i frikshmi Schienenersatzverkehr.",
  "Everything a devoted partner actually says in German: the full \"Ich liebe dich\" ladder with its register traps, the pet names Germans really use, missing-you and thinking-of-you lines, heartfelt compliments, and the everyday good-morning/good-night tenderness that carries a relationship.": "Gjithçka që thotë vërtet në gjermanisht dikush që dashuron me gjithë zemër: e gjithë shkalla deri te «Ich liebe dich» me kurthet e saj të regjistrit, emrat përkëdhelës që gjermanët i përdorin vërtet, fjalët për «më mungon» dhe «po mendoj për ty», komplimentet nga zemra dhe butësia e përditshme nga «mirëmëngjes» te «natën e mirë», që e mban gjallë një lidhje.",
  "Best-friend register: the art of German gossip — lästern is a social sport with strict confidentiality rules (\"Das bleibt unter uns\", \"Kein Wort zu niemandem\") — plus saying what you REALLY think about people, from \"Was ich an ihr mag, ist...\" to the devastating \"Er ist eigentlich ganz nett, aber...\". And the fear chapter: spiders in the bathtub, Höhenangst, Flugangst, nightmares — with the comfort lines (\"Keine Angst, ich bin ja da\") that take the fear away.": "Toni mes miqve më të ngushtë: arti gjerman i thashethemeve — lästern është sport shoqëror me rregulla të rrepta fshehtësie («Das bleibt unter uns», «Kein Wort zu niemandem») — si dhe të thuash çfarë mendon VËRTET për njerëzit, nga «Was ich an ihr mag, ist...» te fjalia vrastare «Er ist eigentlich ganz nett, aber...». Dhe kapitulli i frikës: merimangat në vaskë, Höhenangst, Flugangst, makthet — me fjalët ngushëlluese («Keine Angst, ich bin ja da») që ta largojnë frikën.",
  "The argument survival kit: how Germans actually disagree, hold their ground, blow off steam without getting vulgar — and, most importantly, how they climb back down. Fair-fighting lines, the heated phrases you'll hear (and should recognise as warning signs), and the apology-and-repair language that saves relationships: from \"Es tut mir wirklich leid\" to \"Vertragen wir uns wieder?\".": "Paketa e mbijetesës për zënkat: si e shprehin vërtet gjermanët mospajtimin, si e mbajnë qëndrimin, si e shfryjnë inatin pa u bërë vulgarë — dhe, mbi të gjitha, si zbresin sërish nga kali. Fjali për t'u grindur ndershëm, shprehjet e nxehta që do t'i dëgjosh (dhe duhet t'i njohësh si shenja paralajmërimi), dhe gjuha e kërkimit të faljes dhe e pajtimit që shpëton lidhjet: nga «Es tut mir wirklich leid» te «Vertragen wir uns wieder?».",
  "The hard territory no phrasebook covers: disclosing trust issues (\"Ich hab Vertrauensprobleme\"), the full cheating vocabulary — fremdgehen vs betrügen, Seitensprung vs Affäre — catching, forgiving (or not), and the eternal men-vs-women discourse from warm \"Typisch Mann!\" banter to serious Gleichberechtigung debates.": "Terreni i vështirë që s'e mbulon asnjë libër frazash: të rrëfesh problemet me besimin («Ich hab Vertrauensprobleme»), i gjithë fjalori i tradhtisë — fremdgehen kundrejt betrügen, Seitensprung kundrejt Affäre — kapja në flagrancë, falja (ose jo), dhe debati i përjetshëm burra kundër grash, nga shakatë e ngrohta me «Typisch Mann!» te debatet serioze për Gleichberechtigung.",
  "Frequency-ranked everyday German, bank ranks 1231–1304.": "Gjermanishtja e përditshme e renditur sipas shpeshtësisë, vendet 1231–1304 në bankën e fjalëve.",
